 10	} mitigation_options[] = {
 11		{ "off",               SPECTRE_V2_CMD_NONE,              false },
 12		{ "on",                SPECTRE_V2_CMD_FORCE,             true },
 13		{ "retpoline",         SPECTRE_V2_CMD_RETPOLINE,         false },
 14		{ "retpoline,amd",     SPECTRE_V2_CMD_RETPOLINE_AMD,     false },
 15		{ "retpoline,generic", SPECTRE_V2_CMD_RETPOLINE_GENERIC, false },
 16		{ "auto",              SPECTRE_V2_CMD_AUTO,              false },
 17	};
 18	
 19	static enum spectre_v2_mitigation_cmd __init spectre_v2_parse_cmdline(void)
 20	{
 21		char arg[20];
 22		int ret, i;
 23		enum spectre_v2_mitigation_cmd cmd = SPECTRE_V2_CMD_AUTO;
 24	
 25		if (cmdline_find_option_bool(boot_command_line, "nospectre_v2"))
 26			return SPECTRE_V2_CMD_NONE;
 27		else {
 28			ret = cmdline_find_option(boot_command_line, "spectre_v2", arg, sizeof(arg));
 29			if (ret < 0)
 30				return SPECTRE_V2_CMD_AUTO;
 31	
 32			for (i = 0; i < ARRAY_SIZE(mitigation_options); i++) {
 33				if (!match_option(arg, ret, mitigation_options[i].option))
 34					continue;
 35				cmd = mitigation_options[i].cmd;
 36				break;
 37			}
 38	
 39			if (i >= ARRAY_SIZE(mitigation_options)) {
 40				pr_err("unknown option (%s). Switching to AUTO select\n", arg);
 41				return SPECTRE_V2_CMD_AUTO;
 42			}
 43		}
 44	
 45		if ((cmd == SPECTRE_V2_CMD_RETPOLINE ||
 46		     cmd == SPECTRE_V2_CMD_RETPOLINE_AMD ||
 47		     cmd == SPECTRE_V2_CMD_RETPOLINE_GENERIC) &&
 48		    !IS_ENABLED(CONFIG_RETPOLINE)) {
 49			pr_err("%s selected but not compiled in. Switching to AUTO select\n", mitigation_options[i].option);
 50			return SPECTRE_V2_CMD_AUTO;
 51		}
 52	
 53		if (cmd == SPECTRE_V2_CMD_RETPOLINE_AMD &&
 54		    boot_cpu_data.x86_vendor != X86_VENDOR_AMD) {
 55			pr_err("retpoline,amd selected but CPU is not AMD. Switching to AUTO select\n");
 56			return SPECTRE_V2_CMD_AUTO;
 57		}
 58	
 59		if (mitigation_options[i].secure)
 60			spec2_print_if_secure(mitigation_options[i].option);
 61		else
 62			spec2_print_if_insecure(mitigation_options[i].option);
 63	
 64		return cmd;
 65	}
 66	
 67	/* Check for Skylake-like CPUs (for RSB handling) */
 68	static bool __init is_skylake_era(void)
 69	{
 70		if (boot_cpu_data.x86_vendor == X86_VENDOR_INTEL &&
 71		    boot_cpu_data.x86 == 6) {
 72			switch (boot_cpu_data.x86_model) {
 73			case INTEL_FAM6_SKYLAKE_MOBILE:
 74			case INTEL_FAM6_SKYLAKE_DESKTOP:
 75			case INTEL_FAM6_SKYLAKE_X:
 76			case INTEL_FAM6_KABYLAKE_MOBILE:
 77			case INTEL_FAM6_KABYLAKE_DESKTOP:
 78				return true;
 79			}
 80		}
 81		return false;
 82	}
 83	
 84	static void __init spectre_v2_select_mitigation(void)
 85	{
 86		enum spectre_v2_mitigation_cmd cmd = spectre_v2_parse_cmdline();
 87		enum spectre_v2_mitigation mode = SPECTRE_V2_NONE;
 88	
 89		/*
 90		 * If the CPU is not affected and the command line mode is NONE or AUTO
 91		 * then nothing to do.
 92		 */
 93		if (!boot_cpu_has_bug(X86_BUG_SPECTRE_V2) &&
 94		    (cmd == SPECTRE_V2_CMD_NONE || cmd == SPECTRE_V2_CMD_AUTO))
 95			return;
 96	
 97		switch (cmd) {
 98		case SPECTRE_V2_CMD_NONE:
 99			return;
100	
101		case SPECTRE_V2_CMD_FORCE:
102		case SPECTRE_V2_CMD_AUTO:
103			if (IS_ENABLED(CONFIG_RETPOLINE))
104				goto retpoline_auto;
105			break;
106		case SPECTRE_V2_CMD_RETPOLINE_AMD:
107			if (IS_ENABLED(CONFIG_RETPOLINE))
108				goto retpoline_amd;
109			break;
110		case SPECTRE_V2_CMD_RETPOLINE_GENERIC:
111			if (IS_ENABLED(CONFIG_RETPOLINE))
112				goto retpoline_generic;
113			break;
114		case SPECTRE_V2_CMD_RETPOLINE:
115			if (IS_ENABLED(CONFIG_RETPOLINE))
116				goto retpoline_auto;
117			break;
118		}
119		pr_err("Spectre mitigation: kernel not compiled with retpoline; no mitigation available!");
120		return;
121	
122	retpoline_auto:
123		if (boot_cpu_data.x86_vendor == X86_VENDOR_AMD) {
124		retpoline_amd:
125			if (!boot_cpu_has(X86_FEATURE_LFENCE_RDTSC)) {
126				pr_err("Spectre mitigation: LFENCE not serializing, switching to generic retpoline\n");
127				goto retpoline_generic;
128			}
129			mode = retp_compiler() ? SPECTRE_V2_RETPOLINE_AMD :
130						 SPECTRE_V2_RETPOLINE_MINIMAL_AMD;
131			setup_force_cpu_cap(X86_FEATURE_RETPOLINE_AMD);
132			setup_force_cpu_cap(X86_FEATURE_RETPOLINE);
133		} else {
134		retpoline_generic:
135			mode = retp_compiler() ? SPECTRE_V2_RETPOLINE_GENERIC :
136						 SPECTRE_V2_RETPOLINE_MINIMAL;
137			setup_force_cpu_cap(X86_FEATURE_RETPOLINE);
138		}
139	
140		spectre_v2_enabled = mode;
141		pr_info("%s\n", spectre_v2_strings[mode]);
142	
143		/*
144		 * If neither SMEP nor PTI are available, there is a risk of
145		 * hitting userspace addresses in the RSB after a context switch
146		 * from a shallow call stack to a deeper one. To prevent this fill
147		 * the entire RSB, even when using IBRS.
148		 *
149		 * Skylake era CPUs have a separate issue with *underflow* of the
150		 * RSB, when they will predict 'ret' targets from the generic BTB.
151		 * The proper mitigation for this is IBRS. If IBRS is not supported
152		 * or deactivated in favour of retpolines the RSB fill on context
153		 * switch is required.
154		 */
155		if ((!boot_cpu_has(X86_FEATURE_KAISER) &&
156		     !boot_cpu_has(X86_FEATURE_SMEP)) || is_skylake_era()) {
157			setup_force_cpu_cap(X86_FEATURE_RSB_CTXSW);
158			pr_info("Spectre v2 mitigation: Filling RSB on context switch\n");
159		}
160	
161		/* Initialize Indirect Branch Prediction Barrier if supported */
162		if (boot_cpu_has(X86_FEATURE_IBPB)) {
163			setup_force_cpu_cap(X86_FEATURE_USE_IBPB);
164			pr_info("Spectre v2 mitigation: Enabling Indirect Branch Prediction Barrier\n");
165		}
166	
167		/*
168		 * Retpoline means the kernel is safe because it has no indirect
169		 * branches. But firmware isn't, so use IBRS to protect that.
170		 */
171		if (boot_cpu_has(X86_FEATURE_IBRS)) {
172			setup_force_cpu_cap(X86_FEATURE_USE_IBRS_FW);
173			pr_info("Enabling Restricted Speculation for firmware calls\n");
174		}
175	}
